const https = require('https');
const { URL } = require('url');

function apiRequest(url, options, postData) {
  options = options || {};
  return new Promise((resolve, reject) => {
    try {
      const u = new URL(url);
      const reqHeaders = Object.assign({}, options.headers || {});
      let bodyStr = null;
      if (postData) {
        bodyStr = typeof postData === 'string' ? postData : JSON.stringify(postData);
        reqHeaders['Content-Length'] = Buffer.byteLength(bodyStr);
        if (!reqHeaders['Content-Type']) reqHeaders['Content-Type'] = 'application/json';
      }
      const reqOptions = {
        hostname: u.hostname,
        port: u.port || 443,
        path: u.pathname + u.search,
        method: options.method || 'GET',
        headers: reqHeaders
      };
      const req = https.request(reqOptions, (res) => {
        let raw = '';
        res.on('data', chunk => raw += chunk);
        res.on('end', () => {
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            status: res.statusCode,
            text: () => Promise.resolve(raw),
            json: () => {
              try { return Promise.resolve(JSON.parse(raw)); }
              catch (e) { return Promise.resolve(raw); }
            }
          });
        });
      });
      req.on('error', reject);
      if (bodyStr) req.write(bodyStr);
      req.end();
    } catch (err) {
      reject(err);
    }
  });
}

let input = query;
if (typeof input === 'string') {
  try { input = JSON.parse(input); } catch (e) {}
}

const action = (input.action || 'get').toLowerCase();
const table = (input.table || 'projects').toLowerCase();
const data = input.data || {};
const recordId = input.recordId || data.id || '';

let supabaseUrl = 'https://razkqzmzqdjbhjwyagnt.supabase.co';
let supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJhemtxem16cWRqYmhqd3lhZ250Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODU3NTgxNTYsImV4cCI6MjEwMTMzNDE1Nn0.SQwRIVZVipCkEQFVqqxj9nNar-zCMzIiPcT96820f-U';
let authToken = '';
let serviceRoleKey = '';

try {
  const nodeData = $('Verify Secret Token').first().json || {};
  if (nodeData.supabaseUrl) supabaseUrl = nodeData.supabaseUrl;
  if (nodeData.supabaseKey) supabaseKey = nodeData.supabaseKey;
  if (nodeData.authToken) authToken = nodeData.authToken;
} catch (e) {}

try {
  if (typeof $env !== 'undefined') {
    if ($env.SUPABASE_URL) supabaseUrl = $env.SUPABASE_URL;
    if ($env.SUPABASE_ANON_KEY) supabaseKey = $env.SUPABASE_ANON_KEY;
    if ($env.SUPABASE_SERVICE_ROLE_KEY) serviceRoleKey = $env.SUPABASE_SERVICE_ROLE_KEY;
  }
} catch (e) {}

const bearerToken = serviceRoleKey || authToken || supabaseKey;
const headers = {
  'apikey': serviceRoleKey || supabaseKey,
  'Authorization': 'Bearer ' + bearerToken,
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

const baseUrl = supabaseUrl.replace(/\/+$/, '') + '/rest/v1/' + table;

try {
  if (action === 'get') {
    const url = recordId ? (baseUrl + '?id=eq.' + encodeURIComponent(recordId)) : (baseUrl + '?select=*&limit=30');
    const res = await apiRequest(url, { method: 'GET', headers });
    if (!res.ok) {
      const err = await res.text();
      return JSON.stringify({ error: 'Supabase GET failed (' + res.status + '): ' + err });
    }
    const list = await res.json();
    return JSON.stringify({ success: true, count: Array.isArray(list) ? list.length : 1, data: list });
  }

  if (action === 'create') {
    const prefix = table === 'projects' ? 'proj_' : table === 'experiences' ? 'exp_' : table === 'skills' ? 'skill_' : table === 'blogs' ? 'blog_' : 'rec_';
    const payload = Object.assign({}, data);
    if (!payload.id) {
      payload.id = prefix + Date.now();
    }
    if (table === 'projects') {
      if (!payload.slug) {
        payload.slug = (payload.title || 'project').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '') || ('proj-' + Date.now());
      }
      if (!payload.short_description) payload.short_description = payload.full_description || payload.title || '';
      if (!payload.full_description) payload.full_description = payload.short_description || '';
      if (!Array.isArray(payload.technologies)) {
        payload.technologies = typeof payload.technologies === 'string' ? payload.technologies.split(',').map(t => t.trim()) : [];
      }
      if (!payload.completion_date) payload.completion_date = new Date().toISOString().slice(0, 7);
      if (!payload.status) payload.status = 'completed';
    } else if (table === 'experiences') {
      if (!Array.isArray(payload.responsibilities)) payload.responsibilities = [];
      if (!Array.isArray(payload.achievements)) payload.achievements = [];
      if (!Array.isArray(payload.technologies)) payload.technologies = [];
      if (!payload.employment_type) payload.employment_type = 'Full-time';
    } else if (table === 'skills') {
      if (typeof payload.proficiency !== 'number') payload.proficiency = 85;
      if (!payload.category) payload.category = 'DevOps & Cloud';
    }

    const res = await apiRequest(baseUrl, { method: 'POST', headers }, payload);
    if (!res.ok) {
      const err = await res.text();
      return JSON.stringify({ error: 'Supabase insert failed (' + res.status + '): ' + err });
    }
    const created = await res.json();
    return JSON.stringify({ success: true, action: 'CREATE', table, recordId: payload.id, summary: payload.title || payload.company || payload.name || payload.id, created });
  }

  if (action === 'update') {
    if (!recordId) return JSON.stringify({ error: 'recordId is required for update' });
    const updatePayload = Object.assign({}, data, { updated_at: new Date().toISOString() });
    const res = await apiRequest(baseUrl + '?id=eq.' + encodeURIComponent(recordId), { method: 'PATCH', headers }, updatePayload);
    if (!res.ok) {
      const err = await res.text();
      return JSON.stringify({ error: 'Supabase update failed (' + res.status + '): ' + err });
    }
    const updated = await res.json();
    return JSON.stringify({ success: true, action: 'UPDATE', table, recordId, summary: updatePayload.title || updatePayload.company || updatePayload.name || recordId, updated });
  }

  if (action === 'delete') {
    if (!recordId) return JSON.stringify({ error: 'recordId is required for delete' });
    const res = await apiRequest(baseUrl + '?id=eq.' + encodeURIComponent(recordId), { method: 'DELETE', headers });
    if (!res.ok) {
      const err = await res.text();
      return JSON.stringify({ error: 'Supabase delete failed (' + res.status + '): ' + err });
    }
    return JSON.stringify({ success: true, action: 'DELETE', table, recordId, summary: 'Deleted record ' + recordId + ' from ' + table });
  }

  return JSON.stringify({ error: 'Unknown action: ' + action });
} catch (e) {
  return JSON.stringify({ error: e.message || String(e), stack: e.stack });
}

